<?php
require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../../index.php');if(($_SESSION['admin_role']??'admin')!=='admin'){http_response_code(403);exit('Administrator access required.');}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf_token($_POST['csrf_token']??''))$error='Security token expired.';else{$action=$_POST['action']??'';if($action==='generate'){$sessionId=(int)($_POST['session_id']??0);$r=pg_query_params($conn,'SELECT s.*,e.id event_id,e.fines_enabled,e.absence_fine,e.missing_scan_fine,e.everyone_present_at_timeout FROM event_sessions s JOIN events e ON e.id=s.event_id WHERE s.id=$1',[$sessionId]);if(!$r||!pg_num_rows($r))$error='Session not found.';else{$s=pg_fetch_assoc($r);if($s['fines_enabled']!=='t')$error='Fines are disabled for this event.';else{$abs=(float)$s['absence_fine'];$miss=(float)$s['missing_scan_fine'];pg_query_params($conn,"INSERT INTO fines(attendee_id,event_id,session_id,fine_type,amount,description,issued_by) SELECT r.attendee_id,$1,$2,'absence',$3,$4,$5 FROM event_registrations r LEFT JOIN session_attendance sa ON sa.registration_id=r.id AND sa.session_id=$2 WHERE r.event_id=$1 AND r.status='registered' AND sa.time_in_at IS NULL ON CONFLICT DO NOTHING",[$s['event_id'],$sessionId,$abs,'Absent from '.ucfirst($s['session_name']).' session',$_SESSION['admin_id']]);if($s['everyone_present_at_timeout']!=='t')pg_query_params($conn,"INSERT INTO fines(attendee_id,event_id,session_id,fine_type,amount,description,issued_by) SELECT r.attendee_id,$1,$2,'missing_time_out',$3,$4,$5 FROM event_registrations r JOIN session_attendance sa ON sa.registration_id=r.id AND sa.session_id=$2 WHERE r.event_id=$1 AND r.status='registered' AND sa.time_in_at IS NOT NULL AND sa.time_out_at IS NULL ON CONFLICT DO NOTHING",[$s['event_id'],$sessionId,$miss,'Missing time-out scan for '.ucfirst($s['session_name']).' session',$_SESSION['admin_id']]);audit_log($conn,'session_fines_generated','event_session',$sessionId);redirect('index.php?generated=1');}}}elseif($action==='waive'){$id=(int)($_POST['id']??0);pg_query_params($conn,"UPDATE fines SET status='waived' WHERE id=$1 AND status<>'paid'",[$id]);audit_log($conn,'fine_waived','fine',$id);redirect('index.php');}elseif($action==='manual'){$student=(int)($_POST['attendee_id']??0);$amount=(float)($_POST['amount']??0);$description=trim($_POST['description']??'');if($student&&$amount>0)pg_query_params($conn,"INSERT INTO fines(attendee_id,fine_type,amount,description,issued_by) VALUES($1,'manual',$2,$3,$4)",[$student,$amount,$description,$_SESSION['admin_id']]);redirect('index.php');}}}
$sessions=pg_query($conn,"SELECT s.id,s.session_name,e.title,e.start_at FROM event_sessions s JOIN events e ON e.id=s.event_id WHERE e.fines_enabled=TRUE ORDER BY e.start_at DESC,s.id");$students=pg_query($conn,"SELECT id,attendee_code,full_name FROM attendees WHERE status='active' ORDER BY full_name");$rows=pg_query($conn,"SELECT f.*,a.attendee_code,a.full_name,a.course,a.year_level,a.section,e.title event_title,s.session_name FROM fines f JOIN attendees a ON a.id=f.attendee_id LEFT JOIN events e ON e.id=f.event_id LEFT JOIN event_sessions s ON s.id=f.session_id ORDER BY CASE f.status WHEN 'unpaid' THEN 0 WHEN 'pending_verification' THEN 1 ELSE 2 END,f.created_at DESC");admin_page_start('Fines','fines');?>
<div class="hero"><div><h2><i class="fas fa-gavel"></i> Attendance Fines</h2><p>Generate fines for absences or missing scans and maintain waiver history.</p></div></div><?php if(isset($_GET['generated'])):?><div class="alert">Session fines generated without creating duplicates.</div><?php endif;?><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?><div class="grid two-col"><div class="card"><h3>Generate from session attendance</h3><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="generate"><div class="field full"><label>Event session</label><select name="session_id" required><option value="">Choose session…</option><?php if($sessions):while($s=pg_fetch_assoc($sessions)):?><option value="<?=(int)$s['id']?>"><?=h($s['title'].' · '.ucfirst($s['session_name']))?></option><?php endwhile;endif;?></select></div><div class="field full"><button class="btn">Generate Missing Attendance Fines</button></div></form></div><div class="card"><h3>Manual fine</h3><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="manual"><div class="field"><label>Student</label><select name="attendee_id" required><?php if($students):while($s=pg_fetch_assoc($students)):?><option value="<?=(int)$s['id']?>"><?=h($s['attendee_code'].' · '.$s['full_name'])?></option><?php endwhile;endif;?></select></div><div class="field"><label>Amount</label><input type="number" name="amount" min="0.01" step="0.01" required></div><div class="field full"><label>Description</label><input name="description" required></div><div class="field full"><button class="btn secondary">Issue Fine</button></div></form></div></div><div class="card"><div class="table-wrap"><table><thead><tr><th>Student</th><th>Event / Reason</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if($rows):while($f=pg_fetch_assoc($rows)):?><tr><td><strong><?=h($f['full_name'])?></strong><div class="help"><?=h($f['attendee_code'].' · '.$f['course'].' '.$f['year_level'].' '.$f['section'])?></div></td><td><?=h($f['event_title']?:'Manual fine')?><?= $f['session_name']?' · '.h(ucfirst($f['session_name'])):'' ?><div class="help"><?=h($f['description'])?></div></td><td><strong>₱<?=number_format((float)$f['amount'],2)?></strong></td><td><span class="badge <?=h($f['status'])?>"><?=h(ucwords(str_replace('_',' ',$f['status'])))?></span></td><td><?php if(!in_array($f['status'],['paid','waived'],true)):?><form method="post" data-confirm><?=csrf_field()?><input type="hidden" name="action" value="waive"><input type="hidden" name="id" value="<?=(int)$f['id']?>"><button class="btn small secondary">Waive</button></form><?php endif;?></td></tr><?php endwhile;endif;?></tbody></table></div></div><?php admin_page_end();?>
